using System;
public class Solution { public int MaximumGap(int[] nums) { if (nums.Length < 2) return 0; int low = nums[0], high = nums[0]; foreach (int n in nums) { low = Math.Min(low, n); high = Math.Max(high, n); } if (low == high) return 0; int size = Math.Max(1, (high - low) / (nums.Length - 1)), count = (high - low) / size + 1; var mins = new int[count]; var maxs = new int[count]; var used = new bool[count]; Array.Fill(mins, int.MaxValue); Array.Fill(maxs, int.MinValue); foreach (int n in nums) { int i = (n - low) / size; used[i] = true; mins[i] = Math.Min(mins[i], n); maxs[i] = Math.Max(maxs[i], n); } int best = 0, previous = low; for (int i = 0; i < count; i++) if (used[i]) { best = Math.Max(best, mins[i] - previous); previous = maxs[i]; } return best; } }